CREATE TABLE IF NOT EXISTS module_checks (
  course_id text NOT NULL,
  module_id integer NOT NULL CHECK (module_id > 0),
  question_text text NOT NULL,
  options jsonb NOT NULL CHECK (jsonb_typeof(options) = 'array'),
  correct_index smallint NOT NULL CHECK (correct_index BETWEEN 0 AND 3),
  explanation text NOT NULL,
  published boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (course_id,module_id)
);

ON CONFLICT(course_id,module_id) DO UPDATE SET
  question_text=EXCLUDED.question_text,
  options=EXCLUDED.options,
  correct_index=EXCLUDED.correct_index,
  explanation=EXCLUDED.explanation,
  published=EXCLUDED.published,
  updated_at=now();

CREATE INDEX IF NOT EXISTS module_checks_course_published_idx
  ON module_checks(course_id,published,module_id);
